<?php
require_once __DIR__.'/../config/auth.php';require_role('boss');$pdo=db();$branch=(int)($_GET['branch']??0);$filter=$branch?' AND branch_id=?':'';$args=$branch?[$branch]:[];
$s=$pdo->prepare("SELECT COALESCE(SUM(total),0) sales,COALESCE(SUM(profit),0) gross_profit,COUNT(*) trx FROM transactions WHERE status='paid' AND DATE(created_at)=CURDATE()$filter");$s->execute($args);$sales=$s->fetch();
$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) other_income,COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) expense FROM cash_movements WHERE movement_date=CURDATE()$filter");$s->execute($args);$cash=$s->fetch();$cashIn=(float)$sales['sales']+(float)$cash['other_income'];$netCash=$cashIn-(float)$cash['expense'];
$sql="SELECT b.name,COALESCE(SUM(CASE WHEN t.status='paid' AND DATE(t.created_at)=CURDATE() THEN t.total ELSE 0 END),0) sales,(SELECT COALESCE(SUM(CASE WHEN c.type='income' THEN c.amount ELSE -c.amount END),0) FROM cash_movements c WHERE c.branch_id=b.id AND c.movement_date=CURDATE()) other_flow FROM branches b LEFT JOIN transactions t ON t.branch_id=b.id".($branch?' WHERE b.id=?':'')." GROUP BY b.id ORDER BY sales DESC";$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches WHERE is_active=1 ORDER BY name')->fetchAll();$pageTitle='Kondisi Bisnis';$active='dashboard';include __DIR__.'/../includes/header.php';?>
<section class="card"><form class="filter-row"><label>Cabang<select name="branch"><option value="0">Semua cabang</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>" <?=$branch===$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Tampilkan</button></form></section><div class="grid stats" style="margin-top:18px"><div class="stat-card"><i class="bi bi-cart-check"></i><small>Penjualan hari ini</small><strong><?=rupiah($sales['sales'])?></strong></div><div class="stat-card"><i class="bi bi-arrow-down-circle"></i><small>Total uang masuk</small><strong><?=rupiah($cashIn)?></strong></div><div class="stat-card"><i class="bi bi-arrow-up-circle"></i><small>Pengeluaran</small><strong><?=rupiah($cash['expense'])?></strong></div><div class="stat-card"><i class="bi bi-wallet2"></i><small>Arus kas bersih</small><strong><?=rupiah($netCash)?></strong></div><div class="stat-card"><i class="bi bi-graph-up"></i><small>Laba kotor penjualan</small><strong><?=rupiah($sales['gross_profit'])?></strong></div></div><section class="card"><div class="card-head"><h2>Ringkasan cabang hari ini</h2><a class="btn soft sm" href="laporan.php">Laporan lengkap</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Cabang</th><th>Penjualan</th><th>Arus lain</th><th>Total bersih</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=rupiah($r['sales'])?></td><td><?=rupiah($r['other_flow'])?></td><td><strong><?=rupiah($r['sales']+$r['other_flow'])?></strong></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/../includes/footer.php';?>
